<template>
  <Dialog v-model:open="model">
    <DialogContent class="rounded-lg max-w-lg gap-6">
      <DialogHeader class="gap-y-2 text-left">
        <DialogTitle class="text-xl">Upload Canvasser Interactions CSV</DialogTitle>
        <DialogDescription>
          Upload a CSV file to import canvasser interactions for the selected project.
        </DialogDescription>
      </DialogHeader>

      <div class="flex flex-col gap-4">
        <div class="flex flex-col gap-2">
          <label class="text-sm font-medium">Project</label>
          <Select
            :model-value="selectedProjectId ?? undefined"
            :disabled="!!fixedProjectId || isLoadingProjects"
            @update:model-value="selectedProjectId = $event as string"
          >
            <SelectTrigger :disabled="!!fixedProjectId || isLoadingProjects" data-testid="upload-modal-project-select">
              <SelectValue placeholder="Select a project" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem v-for="p in projects ?? []" :key="p.id" :value="p.id">
                {{ p.name }}
              </SelectItem>
            </SelectContent>
          </Select>
        </div>

        <KitFormFileUpload
          form-id="canvassing-interaction-import-file"
          :file-types="['.csv']"
          :file-size-limit="2"
          size-unit="GB"
          @on-process-data="onFileUploaded"
        />
      </div>

      <DialogFooter>
        <div class="flex flex-wrap justify-end gap-2">
          <DialogClose as-child>
            <Button variant="outline" class="h-10 px-4" data-testid="upload-modal-cancel">Cancel</Button>
          </DialogClose>
          <Button
            class="h-10 px-4"
            :disabled="!s3Url || !selectedProjectId || isSubmitting"
            :loading="isSubmitting"
            data-testid="upload-modal-submit"
            @click="submit"
          >
            Import
          </Button>
        </div>
      </DialogFooter>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import { ref, computed } from 'vue';
import { uploadCanvassingInteractionCsv } from '~/client';
import type { FetchError } from 'ofetch';
import { DialogContent, DialogClose } from '~/components/ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '~/components/ui/select';
import { useSelectorProjectList } from '~/queries/selectors/projects';

const props = defineProps<{
  /** Pre-selected project ID. If provided, project selector is locked. */
  projectId?: string;
}>();

const emit = defineEmits<{
  (e: 'uploaded', importId: string): void;
}>();

const model = defineModel<boolean>({ default: false });

const fixedProjectId = computed(() => props.projectId ?? null);
const selectedProjectId = ref<string | null>(props.projectId ?? null);

const s3Url = ref('');
const fileName = ref('');
const isSubmitting = ref(false);

const { projects, isLoading: isLoadingProjects } = useSelectorProjectList();

function onFileUploaded(data: { privateUrl: string; publicUrl: string; fileName: string } | null) {
  if (data) {
    s3Url.value = data.privateUrl;
    fileName.value = data.fileName;
  } else {
    s3Url.value = '';
    fileName.value = '';
  }
}

async function submit() {
  if (!s3Url.value || !selectedProjectId.value) return;

  isSubmitting.value = true;
  try {
    const response = await uploadCanvassingInteractionCsv({
      composable: '$fetch',
      body: {
        s3_url: s3Url.value,
        file_name: fileName.value,
        project_id: selectedProjectId.value,
      },
    });

    emit('uploaded', response.id);
    model.value = false;
  } catch (error) {
    console.error('Failed to start import:', error);
    showToastError(error as FetchError, 'Failed to start import');
  } finally {
    isSubmitting.value = false;
  }
}
</script>
