import type { CanvassingApplicationName } from '~/client';

export const projectCanvassingAppLabel: Record<CanvassingApplicationName, string> = {
  numinar: 'Numinar',
  pulsar: 'Pulsar',
  advantage: 'Advantage',
  i360: 'i360',
};

export function getProjectCanvassingAppLabel(name: CanvassingApplicationName): string {
  return projectCanvassingAppLabel[name] ?? snakeCaseToCapitalizedCase(name);
}
